/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import CartCollisionsColors from "../../src/CartCollisionsColors.js";
import { LabNotebook } from "../../src/common/model/LabNotebook.js";
import { ElasticScreen } from "../../src/elastic/ElasticScreen.js";
import { ExplosionsScreen } from "../../src/explosions/ExplosionsScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { InelasticScreen } from "../../src/inelastic/InelasticScreen.js";
import { CartCollisionsPreferencesModel } from "../../src/preferences/CartCollisionsPreferencesModel.js";
import { SmartCartsScreen } from "../../src/smart-carts/SmartCartsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from cartCollisionsQueryParameters.
  const simPreferences = new CartCollisionsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // Tables 1 and 2 span the whole lab, so every screen writes to the one notebook.
  const notebook = new LabNotebook();

  const screens = [
    new ExplosionsScreen({
      name: stringManager.getScreenNames().explosionsStringProperty,
      tandem: Tandem.ROOT.createTandem("explosionsScreen"),
      notebook,
      preferences: simPreferences,
      backgroundColorProperty: CartCollisionsColors.backgroundColorProperty,
    }),
    new InelasticScreen({
      name: stringManager.getScreenNames().inelasticStringProperty,
      tandem: Tandem.ROOT.createTandem("inelasticScreen"),
      notebook,
      preferences: simPreferences,
      backgroundColorProperty: CartCollisionsColors.backgroundColorProperty,
    }),
    new ElasticScreen({
      name: stringManager.getScreenNames().elasticStringProperty,
      tandem: Tandem.ROOT.createTandem("elasticScreen"),
      notebook,
      preferences: simPreferences,
      backgroundColorProperty: CartCollisionsColors.backgroundColorProperty,
    }),
    new SmartCartsScreen({
      name: stringManager.getScreenNames().smartCartsStringProperty,
      tandem: Tandem.ROOT.createTandem("smartCartsScreen"),
      notebook,
      backgroundColorProperty: CartCollisionsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { CartCollisionsColors, stringManager, simPreferences, notebook } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
